class LargestRectangle {
  private int[] nextSmallerElement(int[] arr) {
    int n = arr.length;
    int[] nse = new int[n];
    Arrays.fill(nse, n);
    Deque<Integer> stack = new ArrayDeque<>();

    for (int i = n - 1; i >= 0; i--) {
      while (!stack.isEmpty() && arr[stack.getLast()] >= arr[i]) {
        stack.removeLast();
      }
      if (!stack.isEmpty()) {
        nse[i] = stack.getLast();
      }
      stack.addLast(i);
    }
    return nse;
  }

  private int[] prevSmallerElement(int[] arr) {
    int n = arr.length;
    int[] pse = new int[n];
    Arrays.fill(pse, -1);
    Deque<Integer> stack = new ArrayDeque<>();

    for (int i = 0; i < n; i++) {
      while (!stack.isEmpty() && arr[stack.getLast()] >= arr[i]) {
        stack.removeLast();
      }
      if (!stack.isEmpty()) {
        pse[i] = stack.getLast();
      }
      stack.addLast(i);
    }
    return pse;
  }

  public int solve(int[] tiles) {
    int n = tiles.length;
    int[] nse = nextSmallerElement(tiles);
    int[] pse = prevSmallerElement(tiles);

    int maxArea = 0;
    for (int i = 0; i < n; i++) {
      int width = nse[i] - pse[i] - 1;
      int area = width * tiles[i];
      maxArea = Math.max(maxArea, area);
    }
    return maxArea;
  }
}

